'use strict';
const KEY='naval-intelligence-v1';
const stages=['Chiglia e ordinate','Quartabuono e blocchetti','Primo fasciame','Secondo fasciame','Ponti e sovrastrutture','Accessori e finitura','Alberatura','Manovre e vele'];
const lessons=[
{title:'Preparare il cantiere',level:'Principiante',tools:'Piano diritto, squadra, righello, matita, colla per legno.',steps:['Leggi il manuale del kit e identifica i pezzi numerati senza staccarli tutti dalle tavole.','Controlla che chiglia e ordinate siano dritte e integre. Proteggi il piano di lavoro.','Prova a secco ogni incastro; correggi con carta abrasiva fine senza allargare inutilmente le sedi.'],check:'Tutti i componenti sono identificati e la chiglia è diritta.',error:'Incollare prima di verificare gli incastri.'},
{title:'Chiglia e ordinate',level:'Principiante',tools:'Squadra, supporto per chiglia, morsetti piccoli, colla vinilica.',steps:['Fissa la falsa chiglia in posizione verticale su un supporto stabile.','Inserisci le ordinate a secco e verifica che siano perpendicolari e simmetriche rispetto alla chiglia.','Incolla un’ordinata alla volta seguendo le quote del kit. Controlla nuovamente prima che la colla asciughi.'],check:'Guardando lo scheletro da prua e da poppa, i lati appaiono simmetrici.',error:'Forzare gli incastri o lasciare ordinate inclinate.',diagram:'frame'},
{title:'Angolo di quartabuono',level:'Principiante',tools:'Tampone abrasivo lungo, listello flessibile di prova.',steps:['Appoggia un listello di prova lungo più ordinate, senza colla.','Individua dove il listello tocca soltanto uno spigolo o presenta un vuoto.','Smussa progressivamente gli spigoli verso prua e poppa, conservando le linee di riferimento del kit.','Ripeti il controllo a più altezze e su entrambi i lati.'],check:'Il listello appoggia sulle superfici delle ordinate senza salti o pieghe brusche.',error:'Asportare troppo materiale, soprattutto sul bordo di riferimento.',diagram:'fair'},
{title:'Piegare i listelli',level:'Principiante',tools:'Piegalistelli, dima, acqua se adatta al legno, morsetti.',steps:['Prova il listello a secco e identifica dove deve curvarsi.','Usa un ritaglio dello stesso legno per verificare la tecnica. Inumidisci soltanto se adatto al legno e alle istruzioni.','Curva gradualmente su una dima; con un piegalistelli caldo evita scottature e carbonizzazione.','Lascia asciugare e stabilizzare il listello prima di incollarlo.'],check:'Il listello segue la curva senza fessure o torsioni forzate.',error:'Piegare di colpo un listello fragile.'},
{title:'Primo fasciame',level:'Principiante',tools:'Listelli del kit, colla vinilica, morsetti, carta abrasiva.',steps:['Traccia le linee guida secondo il manuale e prova i primi listelli a secco.','Misura gli sviluppi trasversali sulle ordinate e pianifica la distribuzione dei corsi.','Rastrema e curva ogni listello prima di incollarlo. Procedi alternando babordo e tribordo per limitare deformazioni.','Completa i corsi senza forzare i bordi; usa inserti opportunamente sagomati se richiesto dalla geometria.','Dopo l’asciugatura, controlla e leviga gradualmente lo scafo.'],check:'Lo scafo è simmetrico, continuo e senza avvallamenti marcati.',error:'Forzare listelli troppo larghi a prua o incollare tutto un lato per primo.',diagram:'plank'},
{title:'Rastrematura e distribuzione',level:'Intermedio',tools:'Calibro, striscia di carta, righello, lama affilata.',steps:['Misura la lunghezza dell’arco di fasciatura su ciascuna ordinata con una striscia di carta.','Dividi lo scafo in fasce e assegna un numero di corsi coerente con le istruzioni e la geometria.','Calcola la larghezza indicativa di ciascun corso nelle sezioni e raccorda i punti senza cambi bruschi.','Se i listelli diventano troppo stretti o larghi, rivedi la distribuzione: possono servire corsi interrotti o inserti.'],check:'I corsi seguono linee fluide e non terminano in punte fragili.',error:'Usare la stessa rastrematura su tutte le ordinate senza misurare.'},
{title:'Secondo fasciame',level:'Intermedio',tools:'Listelli di finitura, colla compatibile, lama, tampone fine.',steps:['Controlla e correggi il primo fasciame prima di iniziare. Rimuovi polvere e residui.','Pianifica i corsi e lo schema delle giunzioni compatibile con il modello.','Prepara e prova ogni listello. Distribuisci poca colla uniforme e rimuovi subito gli eccessi secondo il tipo di adesivo.','Leviga con delicatezza: i listelli di finitura possono essere molto sottili.'],check:'Le giunzioni sono regolari e la superficie non presenta residui di colla.',error:'Carteggiare aggressivamente e attraversare il secondo fasciame.'},
{title:'Tavolato del ponte',level:'Intermedio',tools:'Listelli, righello, matita, colla, campione per prove.',steps:['Traccia la mezzeria e verifica la disposizione delle aperture.','Pianifica le lunghezze e lo sfalsamento delle giunzioni secondo il modello.','Realizza il calafataggio simulato con una tecnica provata su uno scarto; evita colori troppo marcati.','Incolla i listelli controllando parallelismo e rifila attorno alle aperture.'],check:'Le fughe e le giunzioni sono ordinate e proporzionate alla scala.',error:'Usare una linea di calafataggio sproporzionata.'},
{title:'Colorazione e finitura',level:'Intermedio',tools:'Campioni di legno, abrasivi fini, mordente o vernice compatibile.',steps:['Prova ogni prodotto su uno scarto dello stesso legno, anche in presenza della colla usata.','Proteggi le zone da incollare successivamente e rimuovi la polvere.','Applica strati sottili rispettando i tempi del produttore e lavora con ventilazione adeguata.'],check:'Il colore è uniforme e i dettagli restano leggibili.',error:'Applicare una finitura senza prova preliminare.'},
{title:'Alberi e manovre',level:'Intermedio',tools:'Dime, pinzette, cordame, bozzelli, manuale.',steps:['Identifica gli alberi, i pennoni e i riferimenti delle manovre fisse e correnti.','Controlla inclinazioni e allineamenti secondo i piani prima di fissare gli alberi.','Installa le manovre in una sequenza che permetta l’accesso ai punti interni.','Tendi i cavi gradualmente e in modo simmetrico, senza piegare gli alberi.'],check:'Alberi allineati e cordame ordinato, senza trazioni eccessive.',error:'Tendere un lato completamente prima dell’altro.'}
];
const academyOriginalChecks=[["work","Prima di incollare, cosa controlli?","Identificazione dei pezzi, planarità e incastri."],["frame","Come controlli l’ordinata?","Con squadra e verifica di simmetria."],["fair","Il listello tocca un solo spigolo: cosa fai?","Correggi gradualmente il quartabuono."],["bend","Perché lasci asciugare il listello curvato?","Per stabilizzarne la forma prima della posa."],["plank","Perché alternare i lati?","Per limitare deformazioni asimmetriche."],["taper","Come misuri la fascia?","Con una striscia di carta lungo la curva."],["layers","Perché levigare con delicatezza?","Per non attraversare il sottile rivestimento."],["joints","Come controlli il calafataggio?","Con un campione alla scala corretta."],["finish","Dove provi il mordente?","Su uno scarto dello stesso legno."],["rig","Come tendi le sartie?","Gradualmente e in modo simmetrico."]];
lessons.forEach((l,i)=>{const [diagram,q,answer]=academyOriginalChecks[i];Object.assign(l,{diagram,q,answer})});
lessons.push(...[{"title":"Blocchetti di riempimento a prua e poppa","level":"Principiante","tools":"Balsa o legno del kit, lima, tampone, listello di prova","steps":["Individua le zone in cui il fasciame avrebbe poco appoggio tra ultima ordinata e dritto.","Sagoma i blocchetti a secco e controlla che non coprano battura o incastri previsti.","Incolla e lascia asciugare. Rifinisci con il tampone lungo, seguendo la curva delle ordinate.","Prova il listello su più altezze e confronta i due lati."],"check":"Il listello resta aderente senza essere spinto con forza.","error":"Scavare un avvallamento tra blocchetto e ordinata.","diagram":"fill","q":"Perché usare un listello di prova?","answer":"Per controllare il raccordo reale tra le superfici prima dell’incollaggio."},{"title":"Misurare le ordinate con una striscia di carta","level":"Principiante","tools":"Carta, matita, righello millimetrato","steps":["Segna i limiti della fascia di fasciame su ogni ordinata.","Appoggia una striscia di carta lungo la curva esterna, senza misurare la corda rettilinea.","Segna le estremità e misura la striscia distesa.","Registra le misure in ordine da prua a poppa e ripeti sul lato opposto."],"check":"Le misure rappresentano l’arco effettivo e sono ripetibili.","error":"Misurare la distanza in linea retta invece della superficie curva.","diagram":"arc","q":"Una sezione curva misura 48 mm e la corda 40 mm: quale valore usi?","answer":"48 mm, cioè lo sviluppo superficiale della fascia."},{"title":"Pianificare le fasce del fasciame","level":"Intermedio","tools":"Listelli guida, striscia di carta, matita","steps":["Determina i confini dei corsi secondo il piano del kit.","Posiziona guide flessibili temporanee senza imporre curvature innaturali.","Assegna a ogni fascia un numero preliminare di listelli, poi misura tutte le sezioni.","Correggi il percorso delle guide prima di incollare le tavole."],"check":"Le guide formano linee continue e bilanciate sui due lati.","error":"Distribuire i corsi solo osservando la prua.","diagram":"belts","q":"A cosa servono le fasce?","answer":"A distribuire le larghezze e a controllare il percorso dei corsi in gruppi gestibili."},{"title":"Rastrematura: esempio numerico","level":"Intermedio","tools":"Calibro, matita, righello, tampone","steps":["Supponi che una fascia misuri 60 mm a centro nave, 36 mm a prua e 54 mm a poppa.","Con 12 corsi, calcola le larghezze indicative: 5, 3 e 4,5 mm rispettivamente.","Riporta le quote sulle posizioni delle ordinate e raccordale con una linea fluida.","Asporta il legno gradualmente e prova ogni listello a secco. Ricalcola le larghezze residue durante il lavoro."],"check":"Le larghezze cambiano progressivamente senza punte fragili.","error":"Trattare l’esempio come una misura universale per qualsiasi kit.","diagram":"taper","q":"Con 10 corsi in una fascia larga 35 mm, quanto vale la larghezza media?","answer":"3,5 mm; la distribuzione finale dipende dalla geometria."},{"title":"Sagomatura in pianta (spiling)","level":"Avanzato","tools":"Cartoncino, compasso, tavoletta larga, lama","steps":["Quando un listello rettilineo tende a sollevarsi piegandolo di costa, prepara una dima di cartoncino.","Riporta sulla dima punti della curva del bordo adiacente con un riferimento costante.","Trasferisci i punti su una tavoletta abbastanza larga e raccordali.","Traccia il secondo bordo secondo le larghezze previste, taglia abbondante e rifinisci a secco."],"check":"La tavola segue la curva sul suo piano senza forte pressione laterale.","error":"Confondere la sagomatura del profilo con la piegatura attraverso lo spessore.","diagram":"spile","q":"Quando è utile lo spiling?","answer":"Quando una tavola deve seguire una curva in pianta che un listello diritto non può assumere senza tensione."},{"title":"Corsi interrotti e inserti (drop planks e stealers)","level":"Avanzato","tools":"Listelli, carta, lama, calibro","steps":["Individua se la fascia si restringe o si allarga oltre quanto gestibile con la normale rastrematura.","Riduci il numero di corsi dove serve con una terminazione raccordata; aggiungine uno nelle zone che si allargano.","Disegna prima l’intera giunzione e prepara i pezzi a secco, evitando estremità sottilissime.","Rispetta lo schema storico e il supporto delle giunzioni previsto dal modello."],"check":"Le transizioni non producono vuoti o punte fragili.","error":"Inserire cunei casuali per compensare errori accumulati.","diagram":"drop","q":"Quale intervento può servire dove aumenta la larghezza disponibile?","answer":"Un corso aggiuntivo, se la geometria e il piano lo richiedono."},{"title":"Incollaggio e morsetti del primo fasciame","level":"Principiante","tools":"Colla per legno, morsetti, tamponi protettivi","steps":["Prepara alcuni corsi a secco su entrambi i lati.","Applica una quantità controllata di adesivo secondo le superfici di contatto e le istruzioni.","Blocca senza schiacciare il listello; usa protezioni per evitare impronte.","Alterna i lati, rispetta i tempi di presa e togli subito la colla in eccesso con il metodo adatto."],"check":"Nessun listello si solleva quando si tolgono i morsetti.","error":"Tentare di correggere una curva sbagliata solo aumentando la pressione.","diagram":"clamp","q":"A cosa serve la prova a secco?","answer":"A verificare contatto, forma e posizione prima che la colla renda difficile correggerli."},{"title":"Correggere fessure, gradini e avvallamenti","level":"Intermedio","tools":"Luce radente, tampone lungo, scarti di legno","steps":["Illumina lo scafo lateralmente e controlla con una guida flessibile.","Per una fessura stabile del primo strato, sagoma una scheggia compatibile e incollala; per un listello mobile, risolvi prima il distacco.","Riduci i piccoli risalti con un tampone che appoggi su più zone; ricostruisci gli avvallamenti invece di assottigliare tutto intorno.","Controlla la simmetria e la compatibilità dei prodotti con il secondo fasciame."],"check":"La guida appoggia in modo continuo e lo scafo è stabile.","error":"Coprire una tavola staccata con stucco oppure levigare fino a indebolire il legno.","diagram":"repair","q":"Un listello si muove sotto pressione: stucco o riparazione dell’incollaggio?","answer":"Prima ripristina l’adesione del listello."},{"title":"Preparare il primo fasciame per il secondo","level":"Intermedio","tools":"Tampone, abrasivi, luce, spazzola morbida","steps":["Verifica che il kit preveda realmente un secondo strato.","Controlla raccordi, contorno della chiglia e sedi degli accessori.","Rifinisci con abrasivi progressivi senza alterare le forme; usa una mascherina adatta alle polveri.","Rimuovi polvere e residui, prova colla e listello di finitura su uno scarto."],"check":"Superficie uniforme, stabile e pulita.","error":"Applicare mordente o vernice prima della colla senza verificarne la compatibilità.","diagram":"layers","q":"Il primo fasciame deve essere perfetto esteticamente?","answer":"Deve soprattutto essere stabile, regolare e adatto a ricevere lo strato di finitura."},{"title":"Secondo fasciame: giunzioni e posa","level":"Intermedio","tools":"Listelli di finitura, dima, lama, colla","steps":["Seleziona listelli per tonalità e orientamento della fibra.","Stabilisci il disegno dei corsi e la posizione delle giunzioni secondo i piani.","Prova la tavola, applica poca colla e premi con un tampone morbido senza segnare la superficie.","Sfalsa le giunzioni dove previsto, mantieni i bordi accostati e ripulisci immediatamente.","Controlla ogni corso e rifinisci senza attraversare lo strato sottile."],"check":"Accostamento regolare, nessuna macchia o bolla.","error":"Incollare una tavola fragile sotto torsione o carteggiare troppo.","diagram":"joints","q":"Perché provare prima il colore su uno scarto incollato?","answer":"La colla può modificare l’assorbimento del mordente."},{"title":"Sartie, bigotte e griselle","level":"Intermedio","tools":"Cordame, pinzette, dima, manuale","steps":["Controlla il percorso e i punti di attacco delle sartie sul piano.","Usa una dima per mantenere le bigotte a distanza regolare.","Tendi progressivamente le sartie alternando i lati, senza deformare l’albero.","Realizza le griselle a intervalli coerenti con la scala e verifica l’orizzontalità prevista."],"check":"Le sartie non incurvano l’albero e le griselle non stringono il cordame.","error":"Tendere un lato completamente prima dell’altro.","diagram":"rig","q":"Che cosa controlli durante la tensionatura?","answer":"Allineamento degli alberi e uniformità della tensione."},{"title":"Collaudo finale e conservazione","level":"Avanzato","tools":"Lista di controllo, pennello morbido, supporto","steps":["Controlla simmetria dello scafo, stabilità degli alberi e fissaggio degli accessori.","Verifica che non restino colla, fili liberi o parti taglienti.","Fissa il modello a un supporto stabile e documentalo con fotografie.","Proteggi da sole diretto, polvere, umidità e urti; pulisci con strumenti delicati."],"check":"Il modello è stabile e documentato.","error":"Sollevare la nave afferrando alberi o manovre.","diagram":"stand","q":"Dove si impugna il modello per spostarlo?","answer":"Dal supporto o da punti strutturali sicuri, non dall’alberatura."}]);
const glossary=[['Babordo','Lato sinistro guardando verso prua.'],['Tribordo','Lato destro guardando verso prua.'],['Chiglia','Elemento longitudinale principale dello scafo.'],['Ordinata','Elemento trasversale che definisce la forma dello scafo.'],['Quartabuono','Smussatura dei bordi delle ordinate per dare appoggio al fasciame.'],['Fasciame','Insieme dei corsi di tavole che rivestono lo scafo.'],['Corso','Fila longitudinale di tavole o listelli.'],['Rastrematura','Riduzione progressiva della larghezza di un listello.'],['Calafataggio','Sigillatura delle giunzioni fra tavole, simulata nei modelli.'],['Sartie','Manovre fisse che sostengono lateralmente gli alberi.'],['Griselle','Piccoli cavi trasversali che formano i gradini sulle sartie.'],['Bozzello','Elemento con puleggia per il passaggio del cordame.'],['Baglio','Elemento trasversale che sostiene il ponte.'],['Pennone','Asta trasversale per sostenere una vela quadra.'],['Dritto di poppa','Elemento strutturale nella zona poppiera.']];
const empty=()=>({projects:[],done:[],notes:[]});let state=empty(),tab='home',projectId=null,lessonId=null,noticeTimer,installEvent;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.projects)&&Array.isArray(s.done))state=s;}catch(e){}
const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);const num=x=>Number(x);const fmt=x=>Number(x).toLocaleString('it-IT',{maximumFractionDigits:2});const pct=p=>Math.round(p.completed.length/stages.length*100);const today=()=>new Date().toLocaleDateString('it-IT');
function notice(t){$('notice').textContent=t;$('notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){notice('Memoria non disponibile o piena. Esporta un backup.');return false}}
function progress(n){return `<div class="progress" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="100"><div style="width:${n}%"></div></div>`}
function go(t){if(tab==='illustrated'&&t!=='illustrated'){pdfSession++;pdfBusy=false;if(pdfDoc){pdfDoc.destroy().catch(()=>{});pdfDoc=null}}tab=t;projectId=null;lessonId=null;render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('app').innerHTML=({home,projects,academy,tools,settings,catalog,assistant:assistantPanel,resources:resourcesPanel,scratch:scratchPanel,tutor:tutorPanel,illustrated:illustratedPanel}[tab])();if(tab==='tools'){calculate();runLab()}}
const kits=[{"name":"Albatros","maker":"OcCre","scale":100,"length":null,"level":"Principiante","type":"Goletta","history":"Modello di goletta ispirato ai velieri utilizzati per traffici costieri. Esercitati nella curvatura dei listelli e nelle manovre relativamente semplici.","url":"https://occre.com/en-gb/products/albatros","manual":""},{"name":"Polaris Starter Pack","maker":"OcCre","scale":50,"length":580,"level":"Principiante","type":"Veliero didattico","history":"Kit concepito per avvicinarsi al modellismo navale. Utile per apprendere la preparazione dello scheletro e il fasciame.","url":"https://occre.com/en-gb/products/polaris-starter-pack","manual":""},{"name":"Buccaneer","maker":"OcCre","scale":100,"length":565,"level":"Principiante","type":"Veliero pirata","history":"Progetto originale del produttore ispirato all'immaginario piratesco, non replica documentata di una nave precisa.","url":"https://occre.com/en/products/buccaneer","manual":""},{"name":"Endurance","maker":"OcCre","scale":70,"length":754,"level":"Intermedio","type":"Esplorazione","history":"Nave legata alla spedizione antartica di Ernest Shackleton del 1914. Il modello permette di studiare scafo, sovrastrutture e attrezzature di una nave da esplorazione.","url":"https://occre.com/en-gb/products/endurance","manual":""},{"name":"HMS Beagle","maker":"OcCre","scale":60,"length":720,"level":"Intermedio","type":"Esplorazione","history":"Il brigantino è celebre per il viaggio scientifico di Charles Darwin, iniziato nel 1831. Richiede cura nella preparazione dello scafo e delle manovre.","url":"https://occre.com/en-gb/products/hms-beagle","manual":""},{"name":"HMS Endeavour","maker":"OcCre","scale":54,"length":null,"level":"Avanzato","type":"Esplorazione","history":"La nave del primo viaggio di James Cook nel Pacifico, dal 1768. Modello con numerosi dettagli e alberatura articolata.","url":"https://occre.com/en-gb/products/endeavour","manual":""},{"name":"San Juan Nepomuceno","maker":"Artesanía Latina","scale":90,"length":null,"level":"Avanzato","type":"Vascello","history":"Vascello spagnolo da 74 cannoni che partecipò alla battaglia di Trafalgar nel 1805. Costruzione impegnativa per numero di particolari e manovre.","url":"https://artesanialatina.net/uk/en/488-wooden-model-ship-kit-san-juan-nepomuceno.html","manual":""},{"name":"HMS Bounty – Jolly Boat","maker":"Artesanía Latina","scale":25,"length":null,"level":"Principiante","type":"Lancia","history":"Imbarcazione di servizio della Bounty, nave associata all'ammutinamento del 1789. Progetto adatto a esercitarsi sulle forme dello scafo.","url":"https://artesanialatina.net/uk/en/433-new-jolly-boat-hms-bounty-125-wooden-model-ship-kit.html","manual":""},{"name":"HMS Bounty","maker":"Artesanía Latina","scale":48,"length":null,"level":"Avanzato","type":"Veliero mercantile","history":"Nave britannica utilizzata per il trasporto di piante dell'albero del pane. Il kit prevede la possibilità di mostrare parte degli interni.","url":"https://artesanialatina.net/uk/en/486-merchant-vessel-hms-bounty-148-wooden-model-ship-kit.html","manual":""},{"name":"Pen Duick – Easy","maker":"Artesanía Latina","scale":56,"length":null,"level":"Principiante","type":"Yacht","history":"Cutter da regata associato al navigatore Éric Tabarly. Versione semplificata per i primi lavori.","url":"https://artesanialatina.net/uk/en/62616-easy-kit-cutter-pen-duick-1-56-wooden-model-ship.html","manual":""},{"name":"Pen Duick","maker":"Artesanía Latina","scale":28,"length":null,"level":"Intermedio","type":"Yacht","history":"Versione più grande del cutter da regata, pensata per modellisti con esperienza intermedia.","url":"https://artesanialatina.net/uk/en/62507-pen-duick-french-cutter-1-28-wooden-model-ship-kit.html","manual":""},{"name":"Lady Nelson","maker":"Amati","scale":64,"length":null,"level":"Intermedio","type":"Cutter","history":"Cutter britannico a vela; consigliato per sviluppare precisione nello scafo e nella disposizione del cordame.","url":"https://www.amatimodel.com/en/box-mounting-victory-by-amati/product-lady-nelson-b130001.html","manual":""},{"name":"Rattlesnake","maker":"Model Shipways","scale":64,"length":711.2,"level":"Avanzato","type":"Corsaro","history":"Corsaro americano del periodo della guerra d'indipendenza. Il kit richiede attenzione alle linee dello scafo, alle giunzioni e all'alberatura.","url":"https://www.modelexpo-online.com/products/model-shipways-rattlesnake-us-privateer-1-64-scale","manual":"https://modelexpo-online.com/assets/images/documents/MS2028_Rattlesnake-Instructions-Complete.pdf"},{"name":"Lowell Grand Banks Dory","maker":"Model Shipways","scale":24,"length":null,"level":"Principiante","type":"Barca da pesca","history":"Piccola imbarcazione da pesca dei Grand Banks. Fa parte della serie didattica del produttore.","url":"https://www.modelexpo-online.com/products/model-shipways-lowell-grand-banks-dory-with-tools-1-24-scale-skill-level-i-of-the-shipwright-learning-series","manual":"https://modelexpo-online.com/assets/images/Dory%20instructions%20final.pdf"}];
