let illustratedId=null, pdfDoc=null, pdfPage=1,pdfZoom=1,pdfSession=0,pdfBusy=false;
function visualCards(p){
 const imgs=projectVisuals[p.name]||[];
 if(!imgs.length)return '<p class="muted">Fotografia specifica non ancora disponibile con licenza verificata. Consulta la fonte del progetto.</p>';
 return imgs.map(([file,author,license,lic,caption,url])=>{
 const source='https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(file), image=url||'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(file)+'?width=960';
 return '<figure style="margin:12px 0"><a href="'+esc(source)+'" target="_blank" rel="noopener noreferrer"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="'+esc(image)+'" alt="'+esc(caption+' — '+p.name)+'" style="width:100%;max-height:420px;object-fit:contain;border-radius:10px;background:#eee7d9"></a><figcaption><small>'+esc(caption)+' · '+esc(author)+' · <a href="'+esc(lic)+'" target="_blank" rel="noopener noreferrer">'+esc(license)+'</a> · <a href="'+esc(source)+'" target="_blank" rel="noopener noreferrer">Fonte / originale</a>. Immagine non ritoccata, visualizzata in scala ridotta.</small></figcaption></figure>';
 }).join('');
}
function illustratedPanel(){
 const p=scratchPlans[illustratedId];if(!p)return '<button data-go="scratch">Torna alla biblioteca</button>';
 return '<button class="secondary" data-go="scratch">← Biblioteca dei progetti</button><h1 class="spaced">'+esc(p.name)+'</h1><button class="easy-action" data-easy-start="'+illustratedId+'">Costruisci con Betta →</button><span class="badge spaced">'+esc(p.status)+'</span><p>'+esc(p.source+' · '+p.type)+'</p><section class="card"><h2>Come appare la nave</h2>'+visualCards(p)+'</section><section class="card"><h2>1. Trova i disegni di costruzione</h2><p>'+esc(p.note)+'</p><p>Scala, dimensioni, spessori e distinta materiali: verificare sulle tavole originali; non sono stime inventate.</p><p><a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Fonte e archivio originale ↗</a></p>'+(p.pdf?'<div class="row"><button data-pdf-remote>Visualizza il PDF qui</button><a href="'+esc(p.pdf)+'" target="_blank" rel="noopener noreferrer">Scarica o apri il PDF originale ↗</a></div>':'<p>Non è disponibile un PDF diretto verificato per questa scheda. Scaricalo dalla fonte se disponibile.</p>')+'</section><section class="card"><h2>2. Apri un disegno dal telefono</h2><p>Se hai scaricato un PDF, premi il campo qui sotto e cercalo nella cartella Download. Se hai uno ZIP, aprilo in I miei file e scegli Estrai; poi seleziona il PDF estratto. I PDF locali restano sul telefono. Serve Internet per caricare il lettore.</p><label for="localPlanPdf">PDF dal telefono (max 40 MB)</label><input id="localPlanPdf" type="file" accept="application/pdf,.pdf"><p id="pdfStatus" role="status">Nessun PDF aperto.</p><div id="pdfControls" hidden><div class="row"><button data-pdf-prev>← Pagina</button><span id="pdfCount"></span><button data-pdf-next>Pagina →</button><button class="secondary" data-pdf-minus>−</button><button class="secondary" data-pdf-plus>+</button></div><div style="overflow:auto;max-height:65vh;margin-top:12px"><canvas id="pdfCanvas" style="display:block;background:white"></canvas></div></div></section><section class="card"><h2>3. Impara a costruire con Betta</h2><p>Inizia il percorso di 14 fasi con i tuoi piani, controlli e consulenza IA facoltativa.</p><button class="easy-action" data-easy-start="'+illustratedId+'">Inizia da zero / riprendi la costruzione →</button></section>';
}
async function openPlanPdf(input){
 const session=++pdfSession;pdfBusy=true;
 if(pdfDoc){try{await pdfDoc.destroy()}catch(e){}pdfDoc=null}
 const status=$('pdfStatus');if(!status)return;
 $('pdfControls').hidden=true;status.textContent='Apertura PDF…';
 try{
 const lib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');
 lib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';
 let options;
 if(typeof input==='string'){options={url:input,withCredentials:false,isEvalSupported:false}}
 else{if(input.size>40*1024*1024)throw Error('PDF troppo grande (max 40 MB).');options={data:new Uint8Array(await input.arrayBuffer()),isEvalSupported:false}}
 const doc=await lib.getDocument(options).promise;
 if(session!==pdfSession||tab!=='illustrated'||!$('pdfCanvas')){await doc.destroy();return}
 pdfDoc=doc;pdfPage=1;pdfZoom=1;pdfBusy=false;await renderPlanPdf();
 }catch(e){if(session===pdfSession&&$('pdfStatus'))$('pdfStatus').textContent='Impossibile visualizzare il PDF. Se proviene da un sito esterno, scaricalo e selezionalo dal telefono. Controlla anche la connessione.'}
 finally{if(session===pdfSession)pdfBusy=false}
}
async function renderPlanPdf(){
 if(!pdfDoc||pdfBusy||!$('pdfCanvas'))return;
 const doc=pdfDoc,session=pdfSession;pdfBusy=true;
 try{
 const page=await doc.getPage(pdfPage);if(session!==pdfSession||!$('pdfCanvas')||tab!=='illustrated')return;
 const canvas=$('pdfCanvas'),base=page.getViewport({scale:1}),width=Math.max(240,Math.min(800,canvas.parentElement.clientWidth||320));
 const scale=Math.min(width/base.width*pdfZoom,3000/Math.max(base.width,base.height)),vp=page.getViewport({scale});
 canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);
 await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;
 if(session!==pdfSession||!$('pdfCount'))return;
 $('pdfCount').textContent=pdfPage+' / '+doc.numPages;$('pdfControls').hidden=false;$('pdfStatus').textContent='PDF aperto · '+Math.round(pdfZoom*100)+'%';
 }catch(e){if(session===pdfSession&&$('pdfStatus'))$('pdfStatus').textContent='Errore durante la visualizzazione della pagina.'}
 finally{if(session===pdfSession)pdfBusy=false}
}
document.addEventListener('change',e=>{if(tab==='illustrated'&&e.target.id==='localPlanPdf'&&e.target.files.length)openPlanPdf(e.target.files[0])});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.illustrated!==undefined){illustratedId=Number(d.illustrated);if(!scratchPlans[illustratedId])return;pdfSession++;if(pdfDoc){pdfDoc.destroy().catch(()=>{});pdfDoc=null}pdfBusy=false;go('illustrated');return}
 if(tab!=='illustrated'||pdfBusy)return;
 if(d.pdfRemote!==undefined){const p=scratchPlans[illustratedId];if(p?.pdf)openPlanPdf(p.pdf)}
 else if(pdfDoc){if(d.pdfPrev!==undefined&&pdfPage>1)pdfPage--;else if(d.pdfNext!==undefined&&pdfPage<pdfDoc.numPages)pdfPage++;else if(d.pdfPlus!==undefined)pdfZoom=Math.min(4,pdfZoom*1.25);else if(d.pdfMinus!==undefined)pdfZoom=Math.max(.75,pdfZoom/1.25);else return;renderPlanPdf()}
});


function isEasy(){return state.easyMode!==false}
