function tutorQuick(pIndex){
 const p=scratchPlans[pIndex];if(!p)return;
 const existing=tutorCourses().find(c=>c.plan===pIndex&&c.done<tutorStages.length);
 if(existing){tutorId=existing.id;tutorReview=null;go('tutor');return}
 const c={id:uid(),name:p.name,plan:pIndex,method:'Da definire',scale:0,done:0,notes:[]};
 if(tutorValid(c)&&tutorSave(c)){tutorId=c.id;tutorReview=null;go('tutor')}
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.easyToggle!==undefined){const old=state.easyMode;state.easyMode=!isEasy();if(!save()){if(old===undefined)delete state.easyMode;else state.easyMode=old;return}render();window.scrollTo(0,0)}
 else if(d.easyResume!==undefined){tutorId=d.easyResume;tutorReview=null;go('tutor')}
 else if(d.easyResumeList!==undefined||d.easyOwn!==undefined){tutorId=null;tutorReview=null;go('tutor');if(d.easyOwn!==undefined)$('tutorStart')?.scrollIntoView({block:'start'})}
 else if(d.easyFirstlesson!==undefined){go('academy');lessonId=lessons.findIndex((l,i)=>!state.done.includes(i));if(lessonId<0)lessonId=0;render();window.scrollTo(0,0)}
 else if(d.easyStart!==undefined)tutorQuick(Number(d.easyStart));
});

