function detail(p){return `<button class="secondary" data-go="projects">← Tutte le navi</button><h1 class="spaced">${esc(p.name)}</h1><p class="muted">${esc(p.maker)} ${p.scale?' · 1:'+esc(p.scale):''}</p><div class="card"><div class="row between"><h2>Avanzamento</h2><span class="big">${pct(p)}%</span></div>${progress(pct(p))}<small>Fasi completate: ${p.completed.length}/${stages.length} (peso uguale per ogni fase)</small>${stages.map((s,i)=>`<label class="check"><input type="checkbox" data-stage="${i}" ${p.completed.includes(i)?'checked':''}>${s}</label>`).join('')}</div><div class="grid"><div class="card"><small>Ore di lavoro</small><div class="big">${fmt(p.logs.reduce((a,l)=>a+l.hours,0))}</div></div><div class="card"><small>Spese registrate</small><div class="big">${esc(p.currency)}${fmt(p.logs.reduce((a,l)=>a+l.cost,0))}</div></div></div><form class="card" id="newLog"><h2>Diario di bordo</h2><label for="logText">Annotazioni</label><textarea id="logText" name="note" required maxlength="2000" placeholder="Che cosa hai fatto oggi?"></textarea><label for="hours">Ore di lavoro</label><input id="hours" type="number" name="hours" min="0" max="10000" step="0.25" value="0"><label for="cost">Spese (${esc(p.currency)})</label><input id="cost" type="number" name="cost" min="0" max="1000000" step="0.01" value="0"><label for="photo">Foto (JPG, PNG, HEIC; ridimensionata)</label><input id="photo" type="file" name="photo" accept="image/*,.heic,.heif"><button type="submit" class="spaced">Salva nel diario</button></form>${p.logs.slice().reverse().map(l=>`<div class="card"><div class="row between"><small>${esc(l.date)} · ${fmt(l.hours)} h · ${esc(p.currency)}${fmt(l.cost)}</small><button class="secondary" data-delete-log="${esc(l.id)}">Elimina</button></div><p style="white-space:pre-wrap">${esc(l.note)}</p>${l.photo&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(l.photo)?`<img class="photo" src="${l.photo}" alt="Foto del diario di costruzione">`:''}</div>`).join('')}<button class="danger" data-delete-project>Elimina progetto</button>`}
function diagram(type){const shapes={...{"work":"<rect x=\"24\" y=\"30\" width=\"250\" height=\"70\" rx=\"5\" fill=\"#d4b28b\"/><path d=\"M55 42V86H115\" stroke=\"#286d6a\" stroke-width=\"8\" fill=\"none\"/><rect x=\"140\" y=\"53\" width=\"105\" height=\"14\" fill=\"#fff8e8\" stroke=\"#795738\"/><text x=\"150\" y=\"125\">Squadra e piano diritto</text>","bend":"<path d=\"M25 95 Q145 0 275 95\" fill=\"none\" stroke=\"#795738\" stroke-width=\"12\"/><path d=\"M25 110 Q145 15 275 110\" fill=\"none\" stroke=\"#286d6a\" stroke-width=\"5\"/><text x=\"150\" y=\"135\">Dima e listello curvato</text>","fill":"<path d=\"M35 100Q90 24 265 55L265 100Z\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M100 43V100 M170 39V100 M235 47V100\" stroke=\"#795738\" stroke-width=\"5\"/><path d=\"M35 100Q60 57 100 43L100 100Z\" fill=\"#286d6a\" opacity=\".65\"/><text x=\"150\" y=\"126\">Blocco di appoggio in prua</text>","arc":"<path d=\"M48 28Q55 110 150 115Q245 110 252 28\" fill=\"none\" stroke=\"#795738\" stroke-width=\"8\"/><path d=\"M38 25Q45 120 150 125Q255 120 262 25\" fill=\"none\" stroke=\"#286d6a\" stroke-width=\"4\" stroke-dasharray=\"5 3\"/><path d=\"M48 28H252\" stroke=\"#888\" stroke-dasharray=\"4 4\"/><text x=\"150\" y=\"19\">Corda ≠ arco</text><text x=\"150\" y=\"141\">Misurare lungo la curva</text>","belts":"<path d=\"M20 35Q150 70 280 35Q245 124 150 124Q55 124 20 35Z\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M27 49Q150 90 273 49 M45 76Q150 112 255 76 M80 104Q150 128 220 104\" stroke=\"#286d6a\" stroke-width=\"4\" fill=\"none\"/><text x=\"150\" y=\"18\">Guide delle fasce</text>","taper":"<path d=\"M25 52L275 40L275 94L25 82Z\" fill=\"#d4b28b\" stroke=\"#795738\" stroke-width=\"2\"/><path d=\"M25 35V101 M150 35V101 M275 35V101\" stroke=\"#286d6a\" stroke-dasharray=\"4 3\"/><text x=\"25\" y=\"24\">3 mm</text><text x=\"150\" y=\"24\">4 mm</text><text x=\"275\" y=\"24\">5 mm</text><text x=\"150\" y=\"125\">Profilo raccordato</text>","spile":"<rect x=\"20\" y=\"20\" width=\"260\" height=\"100\" fill=\"#e2c49d\" stroke=\"#795738\"/><path d=\"M26 75Q150 5 274 65L274 91Q150 31 26 101Z\" fill=\"#286d6a\" opacity=\".75\"/><text x=\"150\" y=\"138\">Ricavare la curva da legno largo</text>","drop":"<path d=\"M20 30H280V108H20Z\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M20 50H280 M20 88H280 M20 69H280\" stroke=\"#795738\" stroke-width=\"2\"/><path d=\"M120 69Q175 53 280 57L280 69Z\" fill=\"#286d6a\" stroke=\"#795738\"/><text x=\"150\" y=\"129\">Corso aggiuntivo: schema indicativo</text>","clamp":"<rect x=\"45\" y=\"78\" width=\"210\" height=\"17\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M80 80V28H120V68 M220 80V28H180V68\" stroke=\"#286d6a\" stroke-width=\"7\" fill=\"none\"/><rect x=\"106\" y=\"68\" width=\"28\" height=\"8\" fill=\"#795738\"/><rect x=\"166\" y=\"68\" width=\"28\" height=\"8\" fill=\"#795738\"/><text x=\"150\" y=\"120\">Proteggere i punti di pressione</text>","repair":"<path d=\"M20 80H85L105 89L140 80H280\" stroke=\"#795738\" stroke-width=\"12\" fill=\"none\"/><path d=\"M20 64H280\" stroke=\"#286d6a\" stroke-width=\"6\"/><path d=\"M90 77L105 83L124 77\" stroke=\"#b85542\" stroke-width=\"4\" fill=\"none\"/><text x=\"150\" y=\"116\">Guida lunga e avvallamento</text>","layers":"<path d=\"M28 28Q150 160 272 28\" stroke=\"#795738\" stroke-width=\"17\" fill=\"none\"/><path d=\"M19 35Q150 182 281 35\" stroke=\"#286d6a\" stroke-width=\"5\" fill=\"none\"/><text x=\"150\" y=\"25\">Primo strato: supporto</text><text x=\"150\" y=\"143\">Secondo strato: finitura</text>","joints":"<rect x=\"20\" y=\"24\" width=\"260\" height=\"88\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M20 46H280M20 68H280M20 90H280M95 24V46M190 24V46M55 46V68M155 46V68M245 46V68M110 68V90M210 68V90M65 90V112M165 90V112\" stroke=\"#795738\" stroke-width=\"2\"/><text x=\"150\" y=\"137\">Giunzioni sfalsate: esempio</text>","finish":"<rect x=\"30\" y=\"30\" width=\"110\" height=\"78\" fill=\"#d4b28b\"/><rect x=\"160\" y=\"30\" width=\"110\" height=\"78\" fill=\"#9c6e42\"/><text x=\"85\" y=\"127\">Grezzo</text><text x=\"215\" y=\"127\">Campione</text>","rig":"<path d=\"M150 12V118\" stroke=\"#795738\" stroke-width=\"6\"/><path d=\"M150 25L45 112M150 25L100 112M150 25L200 112M150 25L255 112\" stroke=\"#286d6a\" stroke-width=\"2\"/><path d=\"M82 82H218M65 96H235M100 67H200\" stroke=\"#795738\" stroke-width=\"2\"/><text x=\"150\" y=\"138\">Tensione simmetrica</text>","stand":"<path d=\"M25 30Q150 70 275 30Q238 110 150 107Q62 110 25 30Z\" fill=\"#d4b28b\" stroke=\"#795738\"/><path d=\"M90 98V124H210V98\" stroke=\"#286d6a\" stroke-width=\"7\" fill=\"none\"/><text x=\"150\" y=\"142\">Supporto stabile</text>"},frame:'<path d="M25 109 L265 109" stroke="#6a4329" stroke-width="8"/><path d="M45 108 Q40 50 70 28 Q100 50 95 108 M100 108 Q95 26 145 20 Q195 26 190 108 M195 108 Q190 50 220 28 Q250 50 245 108" fill="none" stroke="#9d7042" stroke-width="8"/><text x="145" y="128" text-anchor="middle">Falsa chiglia e ordinate (schema)</text>',fair:'<path d="M35 100 L80 30 L130 100 M115 100 L160 25 L210 100" stroke="#9d7042" stroke-width="10" fill="none"/><path d="M38 77 Q145 18 253 72" stroke="#286d6a" stroke-width="7" fill="none"/><text x="145" y="125" text-anchor="middle">Listello di prova: appoggio continuo</text>',plank:'<path d="M24 42 Q75 75 270 37 Q238 112 153 118 Q65 116 24 42Z" fill="#c8a274" stroke="#6a4329" stroke-width="2"/><path d="M28 47 Q117 91 266 43 M36 61 Q125 103 254 65 M51 80 Q137 115 234 86 M77 100 Q148 122 213 102" fill="none" stroke="#795738" stroke-width="2"/><text x="150" y="135" text-anchor="middle">Corsi longitudinali (schema)</text>'};return `<svg class="diagram" viewBox="0 0 300 145" role="img" aria-label="Schema didattico semplificato" xmlns="http://www.w3.org/2000/svg" font-size="11" text-anchor="middle" fill="#203540">${shapes[type]||shapes.frame}</svg>`}
function academy(){if(lessonId!==null){const l=lessons[lessonId];return `<button class="secondary" data-go="academy">← Accademia</button><div class="card lesson"><span class="badge">${l.level} · Lezione ${lessonId+1}/${lessons.length}</span><h1 class="spaced">${l.title}</h1>${l.diagram?diagram(l.diagram):''}<small>Schema didattico originale, non in scala.</small><h3>Attrezzi</h3><p>${l.tools}</p><h3 class="spaced">Procedura</h3><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Controllo qualità</h3><p>${l.check}</p><h3 class="spaced">Errore da evitare</h3><p>${l.error}</p><details class="card"><summary>Autoverifica: ${l.q}</summary><p>${l.answer}</p></details><div class="row spaced"><button data-complete="${lessonId}">${state.done.includes(lessonId)?'✓ Completata — annulla':'Segna come completata'}</button>${lessonId<lessons.length-1?`<button class="secondary" data-lesson="${lessonId+1}">Prossima lezione →</button>`:''}</div></div>`}return `<h1>Accademia</h1><div class="card"><h2>Non sai da dove iniziare?</h2><button class="easy-action" data-easy-firstlesson>Inizia o riprendi le lezioni →</button></div><p>22 lezioni con schemi originali, esercizi di autoverifica e procedure. Segui sempre il manuale specifico del tuo kit. Le lezioni 11–20 approfondiscono lo scafo.</p><div class="card"><strong>${state.done.length}/${lessons.length} lezioni completate</strong>${progress(Math.round(state.done.length/lessons.length*100))}</div><div class="card"><h3>Riferimenti tecnici</h3><p><a href="https://www.modelerscentral.com/model-ship-building/planking-tips-for-building-a-model-ship/" target="_blank" rel="noopener noreferrer">Modelers Central: tecniche di fasciatura</a></p><p><a href="https://www.manualslib.com/manual/1087510/Model-Shipways-Charles-W-Morgan.html?page=12" target="_blank" rel="noopener noreferrer">Model Shipways: fasce, corsi e giunzioni</a></p><small>Consultazione facoltativa online. I disegni e le lezioni dell’app sono originali e generici.</small></div>${lessons.map((l,i)=>`<div class="card"><div class="row between"><span class="badge">${l.level} · ${i+1}</span>${state.done.includes(i)?'<strong>✓ Completata</strong>':''}</div><h3 class="spaced">${l.title}</h3><button data-lesson="${i}">Apri lezione</button></div>`).join('')}`}

function planWidths(arcs,n,stock){
 if(!Array.isArray(arcs)||arcs.length<2||arcs.length>30||arcs.some(x=>!Number.isFinite(x)||x<=0||x>100000)||!Number.isInteger(n)||n<1||n>1000||!Number.isFinite(stock)||stock<=0)return null;
 return arcs.map((arc,i)=>({i:i+1,arc,width:arc/n,trim:stock-arc/n,flag:arc/n>stock?'Troppo largo':arc/n<stock/2?'Molto stretto':'Compatibile'}));
}
function readArcs(t){return t.trim().split(/[\s;]+/).filter(Boolean).map(x=>/^\d+(?:[.,]\d+)?$/.test(x)?Number(x.replace(',','.')):NaN)}
function estimateLayer(n,avg,stock,waste,sides){return [n,avg,stock,waste,sides].every(Number.isFinite)&&Number.isInteger(n)&&n>0&&avg>0&&stock>0&&waste>=0&&waste<=100&&[1,2].includes(sides)?Math.ceil(n*avg*sides*(1+waste/100)/stock):null}
function sailSize(base,top,height,den){return [base,top,height,den].every(Number.isFinite)&&base>0&&top>=0&&height>0&&Number.isInteger(den)&&den>0?{base:base*1000/den,top:top*1000/den,height:height*1000/den,area:(base+top)*height/2*1000000/(den*den)}:null}
function labField(id,label,value,step='any',min=0){return '<label for="'+id+'">'+label+'</label><input type="number" id="'+id+'" value="'+value+'" step="'+step+'" min="'+min+'">'}
function labPanel(){
return '<h1 class="spaced">Laboratorio tecnico</h1><p>Misure di modello in mm, salvo indicazione. I valori iniziali sono esempi modificabili, non quote del tuo kit.</p>'+
'<section class="card"><h2>1 · Piano di rastrematura</h2><p>Misura lo sviluppo curvo di una fascia, su ciascuna ordinata dello stesso lato. Inserisci i valori da prua a poppa, separati da spazi o a capo. Usa la virgola o il punto per i decimali.</p><label for="labArcs">Archi delle ordinate (mm)</label><textarea id="labArcs">36 44 55 60 60 54 45</textarea>'+labField('labN','Corsi nella fascia',12,'1',1)+labField('labStock','Larghezza del listello grezzo (mm)',6,'any',0.01)+'<div id="labPlan" aria-live="polite"></div><small>La larghezza media è arco ÷ corsi. Se i corsi diventano troppo stretti o larghi, rivedi le fasce o valuta corsi interrotti e inserti secondo il piano. Il profilo è indicativo, con ordinate equidistanti; non è una dima da taglio.</small></section>'+
'<section class="card"><h2>2 · Stima legno: primo e secondo fasciame</h2><p>Inserisci il numero totale di corsi per lato e la lunghezza media effettiva di un corso, non la lunghezza della nave. Calcola separatamente i due strati.</p><h3>Primo fasciame</h3>'+labField('l1n','Corsi per lato',20,'1',1)+labField('l1avg','Lunghezza media corso (mm)',450)+labField('l1stock','Lunghezza listello commerciale (mm)',500)+labField('l1w','Larghezza listello (mm)',5)+labField('l1t','Spessore listello (mm)',1.5)+labField('l1loss','Scarto aggiuntivo (%)',15)+ '<div id="l1res" aria-live="polite"></div><h3 class="spaced">Secondo fasciame</h3>'+labField('l2n','Corsi per lato',24,'1',1)+labField('l2avg','Lunghezza media corso (mm)',450)+labField('l2stock','Lunghezza listello commerciale (mm)',500)+labField('l2w','Larghezza listello (mm)',4)+labField('l2t','Spessore listello (mm)',0.5)+labField('l2loss','Scarto aggiuntivo (%)',20)+'<div id="l2res" aria-live="polite"></div><small>Stima lineare per due lati: verifica disponibilità delle lunghezze, giunzioni, tagli e venatura. Per un kit a strato singolo considera solo il primo. Il volume indica il legno acquistato, non il volume dello scafo.</small></section>'+
'<section class="card"><h2>3 · Convertire una misura tra due scale</h2>'+labField('labSize','Misura sul modello di partenza (mm)',100)+labField('labFrom','Scala di partenza (1:N)',64,'1',1)+labField('labTo','Scala di arrivo (1:N)',80,'1',1)+'<div id="labScale" class="big" aria-live="polite"></div></section>'+
'<section class="card"><h2>4 · Disegnare una vela triangolare o trapezoidale</h2><p>Inserisci le misure reali in metri. Per una vela triangolare imposta la base superiore a zero. Per il trapezio le due basi devono essere parallele e l’altezza perpendicolare.</p>'+labField('sBase','Base inferiore reale (m)',6)+labField('sTop','Base superiore reale (m)',2)+labField('sHeight','Altezza reale (m)',5)+labField('sDen','Scala (1:N)',64,'1',1)+'<div id="labSail" aria-live="polite"></div><small>Schema geometrico centrato, non sagoma storica. Aggiungi separatamente orli, curvatura e abbondanze secondo i piani.</small></section>';
}
function runLab(){
 if(!$('labArcs'))return;
 const v=id=>$(id).value.trim()===''?NaN:Number($(id).value),valid='Inserisci misure valide.';
 const rows=planWidths(readArcs($('labArcs').value),v('labN'),v('labStock'));
 if(!rows)$('labPlan').textContent='Inserisci da 2 a 30 archi positivi, corsi interi e larghezza positiva.';
 else{
 const max=Math.max(...rows.map(r=>r.width),v('labStock')), dx=240/(rows.length-1),px=i=>30+i*dx,py=w=>115-85*w/max;
 const points=rows.map((r,i)=>px(i).toFixed(2)+','+py(r.width).toFixed(2)).join(' ');
 $('labPlan').innerHTML='<svg class="diagram" viewBox="0 0 300 145" role="img" aria-label="Profilo indicativo della larghezza dei corsi"><path d="M30 115H270" stroke="#795738" fill="none"/><path d="M30 '+py(v('labStock'))+'H270" stroke="#ae8650" stroke-dasharray="4 3"/><polyline points="'+points+'" stroke="#286d6a" stroke-width="3" fill="none"/>'+rows.map((r,i)=>'<circle cx="'+px(i)+'" cy="'+py(r.width)+'" r="3" fill="#286d6a"/>').join('')+'<text x="150" y="137" text-anchor="middle" font-size="11">Prua → ordinate → poppa</text></svg><small>Linea tratteggiata: larghezza grezza.</small><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px;text-align:left"><thead><tr><th>Ord.</th><th>Arco</th><th>Corso</th><th>Asporta</th><th>Esito</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+r.i+'</td><td>'+fmt(r.arc)+'</td><td>'+fmt(r.width)+'</td><td>'+(r.trim<0?'—':fmt(r.trim))+'</td><td>'+r.flag+'</td></tr>').join('')+'</tbody></table></div>';
 }
 for(const p of ['l1','l2']){
 const n=v(p+'n'),avg=v(p+'avg'),stock=v(p+'stock'),w=v(p+'w'),t=v(p+'t'),loss=v(p+'loss'),count=estimateLayer(n,avg,stock,loss,2);
 $(p+'res').innerHTML=count===null||!(w>0&&t>0&&Number.isFinite(w*t*count*stock))?valid:'<div class="big">'+fmt(count)+' listelli</div><p>Metri da acquistare: '+fmt(count*stock/1000)+' m<br>Volume indicativo: '+fmt(count*stock*w*t/1000)+' cm³</p>';
 }
 const size=v('labSize'),from=v('labFrom'),to=v('labTo');
 $('labScale').textContent=[size,from,to].every(Number.isFinite)&&size>0&&Number.isInteger(from)&&Number.isInteger(to)&&from>0&&to>0?fmt(size*from/to)+' mm':valid;
 const sail=sailSize(v('sBase'),v('sTop'),v('sHeight'),v('sDen'));
 if(!sail)$('labSail').textContent=valid;
 else{
 const k=Math.min(240/Math.max(sail.base,sail.top),85/sail.height),b=sail.base*k/2,t=sail.top*k/2;
 $('labSail').innerHTML='<svg class="diagram" viewBox="0 0 300 145" role="img" aria-label="Schema geometrico della vela"><polygon points="'+(150-b)+',110 '+(150+b)+',110 '+(150+t)+','+(110-sail.height*k)+' '+(150-t)+','+(110-sail.height*k)+'" fill="#d4b28b" stroke="#795738" stroke-width="2"/><path d="M150 110V'+(110-sail.height*k)+'" stroke="#286d6a" stroke-dasharray="4 3"/><text x="150" y="137" text-anchor="middle" font-size="11">Schema proporzionale</text></svg><p>Base inferiore: <b>'+fmt(sail.base)+' mm</b><br>Base superiore: <b>'+fmt(sail.top)+' mm</b><br>Altezza: <b>'+fmt(sail.height)+' mm</b><br>Superficie geometrica: <b>'+fmt(sail.area/100)+' cm²</b></p>';
 }
}
document.addEventListener('input',e=>{if(tab==='tools'&&$('labArcs'))runLab()});

function tools(){return `<h1>Calcolatori</h1><p class="muted">Misure in millimetri, salvo indicazione diversa. I risultati sono orientativi.</p><div class="card"><h2>Scala del modello</h2><label for="real">Misura reale (metri)</label><input id="real" type="number" min="0" step="any" value="40"><label for="den">Denominatore della scala</label><input id="den" type="number" min="1" step="1" value="64"><div class="big" id="scaleResult" aria-live="polite">625 mm · 62,5 cm</div></div><div class="card"><h2>Rastrematura del fasciame</h2><p>Misura l’arco da coprire su una singola ordinata e dividi per il numero di corsi previsti.</p><label for="arc">Arco da rivestire (mm)</label><input id="arc" type="number" min="0" step="any" value="60"><label for="courses">Numero di corsi</label><input id="courses" type="number" min="1" step="1" value="12"><label for="stock">Larghezza del listello disponibile (mm)</label><input id="stock" type="number" min="0" step="any" value="6"><div id="taperResult" class="big" aria-live="polite">5 mm</div><p id="taperNote">Riduzione: 1 mm per listello.</p></div><div class="card"><h2>Cordame in scala</h2><label for="rope">Diametro reale (mm)</label><input id="rope" type="number" min="0" step="any" value="40"><label for="ropeDen">Denominatore scala</label><input id="ropeDen" type="number" min="1" step="1" value="64"><div id="ropeResult" class="big" aria-live="polite">0,63 mm</div></div><div class="card"><h2>Stima listelli da acquistare</h2><label for="required">Lunghezza totale stimata dei corsi (m)</label><input id="required" type="number" min="0" step="any" value="12"><label for="strip">Lunghezza di un listello (mm)</label><input id="strip" type="number" min="1" step="any" value="500"><label for="waste">Scarto aggiuntivo (%)</label><input id="waste" type="number" min="0" step="any" value="15"><div id="stripResult" class="big" aria-live="polite">28 listelli</div><small>Stima lineare: verifica anche tagli, giunzioni e larghezze.</small></div>`+labPanel()}

function backupSummary(){
 const bytes=new Blob([JSON.stringify(state)]).size,photos=state.projects.reduce((n,p)=>n+p.logs.filter(l=>l.photo).length,0);
 return '<div class="grid"><div><small>Navi</small><div class="big">'+state.projects.length+'</div></div><div><small>Foto nel diario</small><div class="big">'+photos+'</div></div><div><small>Percorsi</small><div class="big">'+tutorCourses().length+'</div></div></div><p>Dimensione dati JSON: circa '+fmt(bytes/1024)+' KB (non è la quota del browser). Salva una copia su un dispositivo o in una cartella sicura prima di importare un backup o cancellare i dati del sito.</p>';
}

function settings(){return `<h1>Altro</h1><div class="card"><h2>Come vuoi usare l’app?</h2><p>Modalità semplice: meno pulsanti e spiegazioni per principianti. Modalità completa: tutte le opzioni tecniche.</p>${modeButton()}</div><div class="card"><h2>Privacy e informazioni</h2><p>Il diario, le fotografie e i progressi restano nella memoria locale di questo browser. Non vengono sincronizzati su un server dell’app. Il convertitore HEIC scarica una libreria esterna; i siti collegati, incluso ChatGPT, hanno condizioni e privacy proprie. L’hosting può registrare richieste di rete. Prima di condividere immagini, rimuovi informazioni personali.</p><p><a href="privacy.html" target="_blank" rel="noopener noreferrer">Informativa sulla versione web ↗</a></p><small>Versione candidata al rilascio: non ancora approvata dagli store.</small></div><div class="card"><h2>Enciclopedia delle navi</h2><button data-go="catalog">Esplora i modelli</button></div><div class="card"><h2>Dizionario navale</h2><label for="search">Cerca un termine</label><input id="search" type="search" placeholder="Es. quartabuono"><div id="glossary">${glossaryHTML('')}</div></div><div class="card"><h2>Backup dei tuoi dati</h2>${backupSummary()}<p>I progetti e le foto sono conservati sul dispositivo, nel browser. Esporta periodicamente un backup JSON. Cancellare i dati del sito può far perdere il diario.</p><div class="row"><button data-export>Esporta backup</button><button class="secondary" data-import>Importa backup</button></div><input id="backupFile" type="file" accept="application/json,.json" hidden></div><div class="card"><h2>Installazione</h2><p>Pubblica i file su un hosting HTTPS. In Chrome Android apri il menu ⋮ e scegli Installa app o Aggiungi a schermata Home. Su iPhone usa Safari → Condividi → Aggiungi alla schermata Home.</p><small>Versione 7.2 RC · Il convertitore HEIC richiede Internet al primo caricamento della libreria; le immagini vengono elaborate nel browser. Nessun account o servizio a pagamento. Betta Modellista usa regole locali; non analizza foto automaticamente. Il confronto automatico dei prezzi non è incluso.</small></div>`}
function glossaryHTML(q){const s=q.trim().toLowerCase();return glossary.filter(x=>x.join(' ').toLowerCase().includes(s)).map(x=>`<div class="step"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')||'<p>Nessun termine trovato.</p>'}
function calculate(){const val=id=>$(id).value.trim()===''?NaN:num($(id).value);const positive=x=>Number.isFinite(x)&&x>0;const a=val('real'),b=val('den');$('scaleResult').textContent=positive(a)&&positive(b)&&Number.isInteger(b)?`${fmt(a*1000/b)} mm · ${fmt(a*100/b)} cm`:'Inserisci misure valide';const arc=val('arc'),n=val('courses'),stock=val('stock');if(positive(arc)&&positive(n)&&Number.isInteger(n)&&positive(stock)){const w=arc/n;$('taperResult').textContent=fmt(w)+' mm';$('taperNote').textContent=w>stock?'Il corso richiesto supera la larghezza disponibile: rivedi la distribuzione.':`Riduzione: ${fmt(stock-w)} mm per listello.`+(w<stock/2?' Attenzione: valuta una diversa distribuzione dei corsi.':'')}else{$('taperResult').textContent='Inserisci misure valide';$('taperNote').textContent=''}const r=val('rope'),rd=val('ropeDen');$('ropeResult').textContent=positive(r)&&positive(rd)&&Number.isInteger(rd)?fmt(r/rd)+' mm':'Inserisci misure valide';const req=val('required'),strip=val('strip'),waste=val('waste');$('stripResult').textContent=positive(req)&&positive(strip)&&Number.isFinite(waste)&&waste>=0?`${fmt(Math.ceil(req*1000*(1+waste/100)/strip))} listelli`:'Inserisci misure valide'}
let heicLoader;
function loadHeic(){
  if(typeof window.HeicTo==='function')return Promise.resolve(window.HeicTo);
  if(!heicLoader)heicLoader=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='https://cdn.jsdelivr.net/npm/heic-to@1.6.7/dist/iife/heic-to.js';
    const fail=()=>{clearTimeout(timer);script.remove();heicLoader=null;reject(Error('Convertitore HEIC non disponibile. Collegati a Internet e riprova, oppure scegli una foto JPG.'))};
    const timer=setTimeout(fail,30000);
    script.onerror=fail;
    script.onload=()=>{if(typeof window.HeicTo!=='function'){fail();return}clearTimeout(timer);resolve(window.HeicTo)};
    document.head.appendChild(script);
  });
  return heicLoader;
}
function resizePhoto(file){return new Promise((resolve,reject)=>{const im=new Image(),url=URL.createObjectURL(file);im.onload=()=>{try{const c=document.createElement('canvas'),f=Math.min(1,1000/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*f));c.height=Math.max(1,Math.round(im.height*f));c.getContext('2d').drawImage(im,0,0,c.width,c.height);const result=c.toDataURL('image/jpeg',.7);if(!result.startsWith('data:image/jpeg;base64,'))throw Error('Conversione JPEG non riuscita.');resolve(result)}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Impossibile leggere la foto. Prova con JPG o PNG.'))};im.src=url})}
async function photo(file){
  if(!file||!file.size)return '';
  if(file.size>25*1024*1024)throw Error('Foto troppo grande (max 25 MB).');
  try{return await resizePhoto(file)}catch(err){
    if(!/\.(heic|heif|heics|heifs)$/i.test(file.name||'')&&!/image\/(heic|heif)/i.test(file.type||''))throw err;
  }
  notice('Conversione della foto HEIC in corso…');
  const convert=await loadHeic();
  let jpeg;
  try{jpeg=await convert({blob:file,type:'image/jpeg',quality:0.8})}catch(err){throw Error('Questa foto HEIC non è convertibile. Prova con una copia JPG o PNG.')}
  return resizePhoto(jpeg);
}
function validBackup(s){if(s&&s.scratchCourses!==undefined&&(!Array.isArray(s.scratchCourses)||!s.scratchCourses.every(tutorValid)))return false;const str=x=>typeof x==='string',nat=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0;return s&&Array.isArray(s.projects)&&Array.isArray(s.done)&&s.done.every(i=>Number.isInteger(i)&&i>=0&&i<lessons.length)&&s.projects.every(p=>p&&str(p.id)&&/^[a-zA-Z0-9-]+$/.test(p.id)&&str(p.name)&&str(p.maker)&&['£','€','$'].includes(p.currency)&&(p.scale===''||nat(p.scale))&&Array.isArray(p.completed)&&p.completed.every(i=>Number.isInteger(i)&&i>=0&&i<stages.length)&&Array.isArray(p.logs)&&p.logs.every(l=>l&&str(l.id)&&str(l.date)&&str(l.note)&&nat(l.hours)&&nat(l.cost)&&str(l.photo)&&(!l.photo||/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(l.photo))))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.tab||d.go){go(d.tab||d.go);return}if(d.project!==undefined){projectId=d.project;render();window.scrollTo(0,0)}else if(d.lesson!==undefined){lessonId=num(d.lesson);render();window.scrollTo(0,0)}else if(d.complete!==undefined){const i=num(d.complete),was=state.done.includes(i);const previous=state.done;state.done=was?state.done.filter(x=>x!==i):[...state.done,i];if(!save()){state.done=previous;return}render();notice(was?'Lezione riaperta':'Lezione completata!')}else if(d.deleteProject!==undefined){if(confirm('Eliminare questo progetto e tutto il diario?')){const previous=state.projects;state.projects=state.projects.filter(p=>p.id!==projectId);if(!save()){state.projects=previous;return}go('projects')}}else if(d.deleteLog!==undefined){if(confirm('Eliminare questa annotazione?')){const p=state.projects.find(p=>p.id===projectId);const previous=p.logs;p.logs=p.logs.filter(l=>l.id!==d.deleteLog);if(!save()){p.logs=previous;return}render()}}else if(d.export!==undefined){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='naval-intelligence-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notice('Backup preparato')}else if(d.import!==undefined){$('backupFile').click()}});
document.addEventListener('input',e=>{if(tab==='tools'&&e.target.tagName==='INPUT')calculate();if(e.target.id==='search')$('glossary').innerHTML=glossaryHTML(e.target.value)});
document.addEventListener('change',async e=>{if(e.target.dataset.stage!==undefined){const p=state.projects.find(p=>p.id===projectId),i=num(e.target.dataset.stage);const previous=p.completed;p.completed=e.target.checked?[...new Set([...p.completed,i])]:p.completed.filter(x=>x!==i);if(!save()){p.completed=previous;render();return}render()}if(e.target.id==='backupFile'&&e.target.files.length){try{const f=e.target.files[0];if(f.size>15*1024*1024)throw Error('Backup troppo grande');const s=JSON.parse(await f.text());if(!validBackup(s))throw Error('Formato backup non valido');if(confirm('Backup: '+s.projects.length+' navi, '+s.done.length+' lezioni, '+(s.scratchCourses||[]).length+' percorsi. Sostituire tutti i dati locali? Esporta prima un backup dei dati attuali.')){const prev=state;state=s;if(!save()){state=prev;return}go('home');notice('Backup importato')}}catch(err){notice(err.message)}}});
document.addEventListener('submit',async e=>{if(!['newProject','newLog'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='newProject'){const name=String(f.get('name')).trim();if(!name){notice('Inserisci il nome');return}const p={id:uid(),name,maker:String(f.get('maker')).trim(),scale:f.get('scale')?num(f.get('scale')):'',currency:f.get('currency'),completed:[],logs:[]};state.projects.push(p);if(!save()){state.projects.pop();return}projectId=p.id;render();window.scrollTo(0,0);notice('Nave aggiunta al cantiere')}else{const p=state.projects.find(p=>p.id===projectId),note=String(f.get('note')).trim();if(!note)return;const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const l={id:uid(),date:today(),note,hours:num(f.get('hours')||0),cost:num(f.get('cost')||0),photo:await photo(f.get('photo'))};p.logs.push(l);if(!save()){p.logs.pop();return}render();notice('Annotazione salvata')}catch(err){notice(err.message||'Errore nel salvataggio')}finally{button.disabled=false}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('install').hidden=false});$('install').addEventListener('click',async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('install').hidden=true}});window.addEventListener('appinstalled',()=>{$('install').hidden=true});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});render();
